import { createState, addTask, toggleTask, deleteTask, setFilter, setQuery, reset, visibleTasks } from './model.mjs';
import { renderHeader } from './Header.mjs';
import { renderSummary } from './Summary.mjs';
import { renderTaskForm } from './TaskForm.mjs';
import { renderFilterBar } from './FilterBar.mjs';
import { renderSearchBox } from './SearchBox.mjs';
import { renderTaskList } from './TaskList.mjs';
import { renderEmptyState } from './EmptyState.mjs';
import { renderStatusMessage } from './StatusMessage.mjs';
import { renderFooter } from './Footer.mjs';
export function renderApp(state) {
  const visible = visibleTasks(state);
  const listHtml = renderTaskList(state);
  const emptyHtml = visible.length === 0 ? renderEmptyState(state) : '';
  return [renderHeader(state), renderSummary(state), renderTaskForm(state), renderFilterBar(state), renderSearchBox(state), listHtml, emptyHtml, renderStatusMessage(state), renderFooter(state)].join('');
}
export function mountApp(root) {
  let state = createState();
  function render() { root.innerHTML = renderApp(state); }
  render();
  root.addEventListener('submit', (e) => {
    const form = e.target.closest('[data-action="add-task"]');
    if (!form) return;
    e.preventDefault();
    const input = form.querySelector('input[name="title"]');
    const title = input ? input.value : '';
    state = addTask(state, title);
    render();
    const newInput = root.querySelector('#task-title-input');
    if (newInput) newInput.focus();
  });
  root.addEventListener('click', (e) => {
    const toggle = e.target.closest('[data-action="toggle-task"]');
    if (toggle) { const id = toggle.getAttribute('data-id'); state = toggleTask(state, id); render(); return; }
    const del = e.target.closest('[data-action="delete-task"]');
    if (del) { const id = del.getAttribute('data-id'); state = deleteTask(state, id); render(); return; }
    const filterBtn = e.target.closest('[data-action="set-filter"]');
    if (filterBtn) { const f = filterBtn.getAttribute('data-filter'); state = setFilter(state, f); render(); return; }
    const resetBtn = e.target.closest('[data-action="reset"]');
    if (resetBtn) { state = reset(state); render(); return; }
  });
  root.addEventListener('input', (e) => {
    const search = e.target.closest('[data-action="search"]');
    if (search) {
      state = setQuery(state, search.value);
      render();
      const newSearch = root.querySelector('[data-action="search"]');
      if (newSearch) { newSearch.focus(); const v = newSearch.value; newSearch.value = ''; newSearch.value = v; if (typeof newSearch.setSelectionRange === 'function') { try { const len = v.length; newSearch.setSelectionRange(len, len); } catch {} } }
      return;
    }
  });
  return { getState: () => state, render };
}

