export function renderEmptyState(state) {
  const tasks = state && Array.isArray(state.tasks) ? state.tasks : [];
  const hasTasks = tasks.length > 0;
  const msg = hasTasks ? 'No matching tasks' : 'No tasks yet. Add a task to get started.';
  return `<div data-component="EmptyState"><p>${msg}</p></div>`;
}

