export function renderFilterBar(state) {
  const current = state && state.filter ? state.filter : 'all';
  function btn(value, label) {
    const selected = current === value;
    const cls = selected ? 'is-selected selected' : '';
    const pressed = selected ? 'true' : 'false';
    return `<button type="button" data-action="set-filter" data-filter="${value}" aria-pressed="${pressed}" class="${cls}">${label}</button>`;
  }
  return `<nav data-component="FilterBar" aria-label="Filter tasks">${btn('all','All')}${btn('active','Active')}${btn('completed','Completed')}</nav>`;
}

