export function renderHeader(state) {
  const total = state && Array.isArray(state.tasks) ? state.tasks.length : 0;
  const label = total === 1 ? '1 task' : `${total} tasks`;
  return `<header data-component="Header"><h1>Clear Tasks</h1><p data-testid="header-total" aria-live="polite">${label}</p></header>`;
}

