export function createState() {
  return { tasks: [], filter: 'all', query: '', status: '', nextId: 1 };
}
export function escapeHtml(text) {
  return String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}
export function addTask(state, title) {
  const trimmed = String(title).trim();
  if (!trimmed) {
    return { tasks: state.tasks.slice(), filter: state.filter, query: state.query, status: 'Task title cannot be empty.', nextId: state.nextId };
  }
  const newTask = { id: String(state.nextId), title: trimmed, completed: false };
  return { tasks: [...state.tasks, newTask], filter: state.filter, query: state.query, status: `Added "${trimmed}"`, nextId: state.nextId + 1 };
}
export function toggleTask(state, id) {
  const sid = String(id);
  let found = false;
  const newTasks = state.tasks.map(t => {
    if (t.id === sid) { found = true; return { ...t, completed: !t.completed }; }
    return t;
  });
  let status = state.status;
  if (found) {
    const toggled = newTasks.find(t => t.id === sid);
    status = toggled && toggled.completed ? 'Task completed.' : 'Task marked as active.';
  }
  return { tasks: newTasks, filter: state.filter, query: state.query, status, nextId: state.nextId };
}
export function deleteTask(state, id) {
  const sid = String(id);
  const exists = state.tasks.some(t => t.id === sid);
  const newTasks = state.tasks.filter(t => t.id !== sid);
  const status = exists ? 'Task deleted.' : state.status;
  return { tasks: newTasks, filter: state.filter, query: state.query, status, nextId: state.nextId };
}
export function setFilter(state, filter) {
  const allowed = ['all', 'active', 'completed'];
  const nextFilter = allowed.includes(filter) ? filter : state.filter;
  return { tasks: state.tasks.slice(), filter: nextFilter, query: state.query, status: state.status, nextId: state.nextId };
}
export function setQuery(state, query) {
  return { tasks: state.tasks.slice(), filter: state.filter, query: String(query), status: state.status, nextId: state.nextId };
}
export function reset(state) {
  return createState();
}
export function visibleTasks(state) {
  const tasks = Array.isArray(state.tasks) ? state.tasks : [];
  const filter = state && state.filter ? state.filter : 'all';
  const rawQuery = state && typeof state.query === 'string' ? state.query : '';
  const query = rawQuery.trim().toLowerCase();
  let out = tasks;
  if (filter === 'active') out = out.filter(t => !t.completed);
  else if (filter === 'completed') out = out.filter(t => t.completed);
  if (query) out = out.filter(t => String(t.title).toLowerCase().includes(query));
  return out;
}

