import { renderApp } from './app.mjs';
describe('model createState/reset', () => {
  it('createState returns empty all filter nextId 1', () => { const s=createState(); assert.deepEqual(s,{tasks:[],filter:'all',query:'',status:'',nextId:1}); });
  it('reset clears tasks filter query status nextId', () => { let s=createState(); s=addTask(s,'a'); s=setFilter(s,'completed'); s=setQuery(s,'hi'); s=toggleTask(s,'1'); let r=reset(s); assert.deepEqual(r,{tasks:[],filter:'all',query:'',status:'',nextId:1}); });
});
describe('addTask', () => {
  it('adds trimmed title with string id and increments nextId', () => { let s=createState(); s=addTask(s,'  hello  '); assert.equal(s.tasks.length,1); assert.equal(s.tasks[0].title,'hello'); assert.equal(s.tasks[0].id,'1'); assert.equal(s.nextId,2); s=addTask(s,'world'); assert.equal(s.tasks[1].id,'2'); });
  it('blank whitespace sets nonempty status and adds nothing', () => { let s=createState(); s=addTask(s,'a'); const before=s; const after=addTask(s,'   '); assert.equal(after.tasks.length,1); assert.ok(after.status.length>0); assert.equal(after.nextId,before.nextId); });
  it('keeps completed false', () => { let s=addTask(createState(),'t'); assert.equal(s.tasks[0].completed,false); });
});
describe('toggle/delete', () => {
  it('toggle flips completed', () => { let s=addTask(createState(),'x'); s=toggleTask(s,'1'); assert.equal(s.tasks[0].completed,true); s=toggleTask(s,'1'); assert.equal(s.tasks[0].completed,false); });
  it('unknown toggle keeps tasks unchanged', () => { let s=addTask(createState(),'x'); const after=toggleTask(s,'999'); assert.equal(after.tasks.length,1); assert.equal(after.tasks[0].title,'x'); });
  it('delete removes by id', () => { let s=createState(); s=addTask(s,'a'); s=addTask(s,'b'); s=deleteTask(s,'1'); assert.equal(s.tasks.length,1); assert.equal(s.tasks[0].id,'2'); });
  it('unknown delete keeps tasks unchanged', () => { let s=addTask(createState(),'a'); const after=deleteTask(s,'nope'); assert.equal(after.tasks.length,1); });
});
describe('filter/search visibleTasks', () => {
  it('filter active/completed', () => { let s=createState(); s=addTask(s,'a'); s=addTask(s,'b'); s=toggleTask(s,'2'); assert.equal(visibleTasks(s).length,2); let a=setFilter(s,'active'); assert.equal(visibleTasks(a).length,1); assert.equal(visibleTasks(a)[0].id,'1'); let c=setFilter(s,'completed'); assert.equal(visibleTasks(c).length,1); assert.equal(visibleTasks(c)[0].id,'2'); });
  it('query case-insensitive trimmed combined with filter', () => { let s=createState(); s=addTask(s,'Buy Milk'); s=addTask(s,'buy bread'); s=addTask(s,'Walk dog'); let q=setQuery(s,'  BUY '); assert.equal(visibleTasks(q).length,2); let f=setFilter(q,'active'); s=toggleTask(s,'1'); f=setFilter(setQuery(s,'buy'),'active'); assert.equal(visibleTasks(f).length,1); });
  it('stable insertion order', () => { let s=createState(); s=addTask(s,'c'); s=addTask(s,'a'); s=addTask(s,'b'); const v=visibleTasks(s); assert.deepEqual(v.map(t=>t.title),['c','a','b']); });
});
describe('immutability', () => {
  it('prior state not mutated', () => { const s0=createState(); const s1=addTask(s0,'hi'); assert.equal(s0.tasks.length,0); assert.equal(s0.nextId,1); const s2=toggleTask(s1,'1'); assert.equal(s1.tasks[0].completed,false); assert.equal(s2.tasks[0].completed,true); const s3=setFilter(s1,'completed'); assert.equal(s1.filter,'all'); const s4=setQuery(s1,'q'); assert.equal(s1.query,''); const s5=deleteTask(s1,'1'); assert.equal(s1.tasks.length,1); });
  it('each operation returns new state object', () => { const s0=createState(); const s1=addTask(s0,'x'); assert.notStrictEqual(s0,s1); const s2=toggleTask(s1,'1'); assert.notStrictEqual(s1,s2); });
