  it('encodes &, <, >, double and single quotes', () => { assert.equal(escapeHtml('&<>"\''), '&amp;&lt;&gt;&quot;&#39;'); assert.equal(escapeHtml('<script>'), '&lt;script&gt;'); assert.equal(escapeHtml('a & b'), 'a &amp; b'); });
