  it('TaskList stable order and EmptyState', () => { let s=createState(); assert.match(renderEmptyState(s),/No tasks yet/); s=addTask(s,'b'); s=addTask(s,'a'); const html=renderTaskList(s); assert.match(html,/data-component="TaskList"/); assert.ok(html.indexOf('data-id="1"')<html.indexOf('data-id="2"')); let f=setFilter(s,'completed'); assert.match(renderEmptyState(f),/No matching tasks/); });
  it('Header and Summary counts', () => { let s=createState(); s=addTask(s,'x'); s=addTask(s,'y'); s=toggleTask(s,'1'); assert.match(renderHeader(s),/2 tasks/); const sum=renderSummary(s); assert.match(sum,/2 total/); assert.match(sum,/1 completed/); assert.match(sum,/1 pending/); });
  it('Footer has Reset', () => { assert.match(renderFooter(createState()),/data-action="reset"/); });
