describe('renderApp integration', () => {
  it('composes all ten markers', () => { let s=createState(); s=addTask(s,'hello'); const html=renderApp(s); ['Header','Summary','TaskForm','FilterBar','SearchBox','TaskList','TaskRow','StatusMessage','Footer'].forEach(c=>assert.match(html,new RegExp('data-component="'+c+'"'))); assert.doesNotMatch(html,/data-component="EmptyState"/); assert.match(renderApp(createState()),/data-component="EmptyState"/); });
  it('escapes user text in app', () => { let s=createState(); s=addTask(s,'<script>alert(1)</script>'); const html=renderApp(s); assert.doesNotMatch(html,/<script>/); assert.match(html,/&lt;script&gt;/); });
