export function renderSummary(state) {
  const tasks = state && Array.isArray(state.tasks) ? state.tasks : [];
  const total = tasks.length;
  const completed = tasks.filter(t => t.completed).length;
  const pending = total - completed;
  return `<section data-component="Summary" aria-label="Task summary"><div data-testid="summary-total">${total} total</div><div data-testid="summary-completed">${completed} completed</div><div data-testid="summary-pending">${pending} pending</div></section>`;
}

