import { renderTaskRow } from './TaskRow.mjs';

function getVisibleTasks(state) {
  const tasks = state && Array.isArray(state.tasks) ? state.tasks : [];
  const filter = state && state.filter ? state.filter : 'all';
  const rawQuery = state && typeof state.query === 'string' ? state.query : '';
  const query = rawQuery.trim().toLowerCase();
  let visible = tasks;
  if (filter === 'active') visible = visible.filter(t => !t.completed);
  else if (filter === 'completed') visible = visible.filter(t => t.completed);
  if (query) visible = visible.filter(t => String(t.title).toLowerCase().includes(query));
  return visible;
}

export function renderTaskList(state) {
  const visible = getVisibleTasks(state);
  const items = visible.map(task => renderTaskRow(task)).join('');
  return `<ul data-component="TaskList">${items}</ul>`;
}

